// Skypane Manager — the words, English (v2.9.0): one table, read by Kit.t(key, vars) (kit.js). Every new piece of
// text since v2.9.0 is here; the rest of the Manager moves in with v2.10.0, and other languages are files like this one
// (strings/de.js …) with the same keys. {name} = a value put in; {one, other} = the plural forms (Intl.PluralRules).
// Whole sentences only — never pieces glued together. Plain data: nothing here is ever parsed as HTML.
window.SKYPANE_STRINGS = window.SKYPANE_STRINGS || {};
