  "panels.alerts.info": "Alerts are made in Hubitat: a rule (Rule Machine, webCoRE …) sends one with the Skypane Notifier driver — a water leak, smoke, a warm freezer, the alarm going off. Which panels get it is part of the rule. Skypane shows it, sounds it, and tells Hubitat when someone dismisses it.",
