  "panels.alerts.quietDamage": "Level 4 sounds in quiet hours",
  "panels.alerts.quietDamageHint": "A leak at night. Off: only a level 5 sounds then — a level 4 still shows full screen.",
  "panels.alerts.levelsFoot": "5 Life safety (gas, smoke, heat, CO, intrusion) and 4 Damage (a leak) fill the screen and ask for the panel PIN to dismiss. 3 Action needed stays until dismissed; 2 Finished and 1 Reminder go after 60 seconds. One alert shows at a time — the highest level, the newest within a level. Dismissing a level 3–5 clears it on every panel; levels 1–2 on that panel only. Hubitat hears every dismissal.",
